import jmespath


def compile_jmespath_expression(expression: str) -> str:
    """Compile a JMESPath expression into an optimized form for repeated use. expression: A JMESPath expression to compile, e.g. 'foo.bar' -> compiled expression string."""
    try:
        compiled = jmespath.compile(expression)
        return str(compiled)
    except Exception as e:
        raise ValueError(f"invalid JMESPath expression: {expression!r}") from e

import jmespath


def search_with_jmespath(expression: str, data: dict[str, object] | list[object]) -> object:
    """Search data using a JMESPath expression to extract specific information. expression: A JMESPath expression to search the data, e.g. 'name' -> 'John'. data: The data structure to search through, e.g. {'age': 30, 'name': 'John'}."""
    try:
        result = jmespath.search(expression, data)
        # jmespath.search should already return JSON-compatible types
        # But let's explicitly handle the case where it might return a generator
        if hasattr(result, '__iter__') and not isinstance(result, (str, bytes, dict, list)):
            return list(result)
        return result
    except Exception as e:
        raise ValueError(f"invalid JMESPath expression or data: {expression!r}") from e

import jmespath.parser
from typing import Any, Dict, List, Union


def parse_jmespath_expression(expression: str) -> Dict[str, Any] | None:
    """Parse a JMESPath expression into an abstract syntax tree for analysis. expression: A JMESPath expression to parse, e.g. 'foo.bar' -> AST representation."""
    parser = jmespath.parser.Parser(lookahead=2)
    try:
        result = parser.parse(expression)
        # Convert ParsedResult to a dictionary manually
        if hasattr(result, '__dict__'):
            # Handle the case where result is a custom object
            return _convert_parsed_result_to_dict(result)
        elif isinstance(result, dict):
            return result
        else:
            return {'value': result}
    except Exception as e:
        raise ValueError(f"Invalid JMESPath expression: {expression!r}") from e


def _convert_parsed_result_to_dict(obj: Any) -> Dict[str, Any]:
    """Recursively convert a ParsedResult object to a dictionary."""
    if hasattr(obj, '__dict__'):
        result = {}
        for key, value in obj.__dict__.items():
            if key.startswith('_'):
                continue
            if isinstance(value, list):
                result[key] = [_convert_parsed_result_to_dict(item) if hasattr(item, '__dict__') else item for item in value]
            elif hasattr(value, '__dict__'):
                result[key] = _convert_parsed_result_to_dict(value)
            else:
                result[key] = value
        return result
    elif isinstance(obj, list):
        return [_convert_parsed_result_to_dict(item) if hasattr(item, '__dict__') else item for item in obj]
    else:
        return obj

import jmespath.lexer


def tokenize_jmespath_expression(expression: str) -> list[dict[str, str | int]]:
    """Break down a JMESPath expression into tokens for parsing. expression: A JMESPath expression to tokenize, e.g. 'foo.bar' -> [{'type': 'unquoted_identifier', 'value': 'foo', 'start': 0, 'end': 3}, {'type': 'literal', 'value': '.', 'start': 3, 'end': 4}, {'type': 'unquoted_identifier', 'value': 'bar', 'start': 4, 'end': 7}]."""
    try:
        lexer = jmespath.lexer.Lexer()
        tokens = list(lexer.tokenize(expression))
        return [
            {
                "type": token["type"],
                "value": token["value"],
                "start": token["start"],
                "end": token["end"]
            }
            for token in tokens
        ]
    except Exception as e:
        raise ValueError(f"Failed to tokenize JMESPath expression: {str(e)}")

import jmespath.visitor


def default_jmespath_visit(node: dict[str, object], options: dict[str, object] | None = None) -> None:
    """Handle default visiting behavior for JMESPath AST nodes during evaluation. node: A JMESPath AST node as a dictionary, options: Optional configuration for the TreeInterpreter. Example: default_jmespath_visit({'type': 'Identifier', 'value': 'foo'}) -> None."""
    try:
        interpreter = jmespath.visitor.TreeInterpreter(options=options)
        interpreter.default_visit(node)
    except NotImplementedError as e:
        raise ValueError(f"Node type not implemented: {node.get('type', 'unknown')!r}") from e
    except Exception as e:
        raise ValueError(f"Error during JMESPath node visit: {str(e)!r}") from e

import jmespath.functions
from typing import List, Any, Dict, Union


def call_jmespath_function(function_name: str, resolved_args: List[Any]) -> Any:
    """Execute a named JMESPath function with provided arguments.

    Args:
        function_name: The name of the JMESPath function to call, e.g. 'length'
        resolved_args: The arguments to pass to the function, e.g. ['hello']

    Returns:
        The result of calling the JMESPath function with the given arguments

    Example:
        >>> call_jmespath_function('length', ['hello'])
        5
    """
    try:
        functions = jmespath.functions.Functions()
        result = functions.call_function(function_name, resolved_args)
        # Convert to JSON-compatible types
        if isinstance(result, (str, int, float, bool)) or result is None:
            return result
        elif isinstance(result, bytes):
            return result.decode('utf-8')
        elif hasattr(result, '__iter__') and not isinstance(result, (str, bytes, dict)):
            # Convert iterables to lists
            return list(result)
        else:
            return str(result)
    except KeyError:
        raise ValueError(f"Unknown JMESPath function: {function_name}")
    except Exception as e:
        raise ValueError(f"Error calling JMESPath function {function_name}: {str(e)}")

def define_jmespath_function_signature(arguments: list[str]) -> None:
    """Define the expected argument types and count for a JMESPath function signature.

    Args:
        arguments: An array of expected argument types and count for a JMESPath function signature

    Example:
        define_jmespath_function_signature(["string", "number"]) -> None
    """
    try:
        # Convert arguments to tuple for the signature function
        _record_signature = _signature(*arguments)
        # Since we're just defining the signature, we don't need to apply it to a function
        # but we validate the arguments are acceptable
        if not isinstance(arguments, list):
            raise ValueError("arguments must be a list")
        for arg in arguments:
            if not isinstance(arg, str):
                raise ValueError("all argument types must be strings")
    except Exception as e:
        raise ValueError(f"invalid arguments for JMESPath function signature: {str(e)}")


def _signature(*arguments):
    def _record_signature(func):
        func.signature = arguments
        return func
    return _record_signature

def create_field_ast_node(name: str) -> dict[str, str | list[dict] | None]:
    """Create an AST node representing a field access in a JMESPath expression. name: The name of the field to access, e.g. 'name' -> {'type': 'field', 'children': [], 'value': 'name'}."""
    if not isinstance(name, str):
        raise ValueError("name must be a string")

    return {"type": "field", "children": [], "value": name}

import jmespath.ast


def create_literal_ast_node(literal_value: object) -> dict[str, object | list[dict[str, object]]]:
    """Create an AST node representing a literal value in a JMESPath expression. literal_value: The literal value to be represented in the AST node, e.g. ["a", "b", "c"] -> {'type': 'literal', 'value': ['a', 'b', 'c'], 'children': []}."""
    try:
        # Convert to string for library call, but preserve original value
        if literal_value is None:
            lib_result = jmespath.ast.literal("null")
            lib_result['value'] = None
        elif isinstance(literal_value, (int, float, bool)):
            lib_result = jmespath.ast.literal(str(literal_value))
            lib_result['value'] = literal_value
        elif isinstance(literal_value, str):
            lib_result = jmespath.ast.literal(literal_value)
        else:
            # For other types like lists, convert to string representation
            lib_result = jmespath.ast.literal(str(literal_value))
            lib_result['value'] = literal_value
        return lib_result
    except Exception as e:
        raise ValueError(f"Failed to create literal AST node: {str(e)}") from e

def create_function_expression_ast_node(name: str, args: list) -> dict[str, str | list]:
    """Create an AST node representing a function call in a JMESPath expression. name: The name of the function to create an AST node for, e.g. 'length' -> {'type': 'function_expression', 'children': [], 'value': 'length'}. args: The arguments passed to the function as AST nodes, e.g. [{'type': 'field', 'value': 'name'}] -> {'type': 'function_expression', 'children': [{'type': 'field', 'value': 'name'}], 'value': 'length'}."""
    if not isinstance(name, str):
        raise ValueError("name must be a string")
    if not isinstance(args, list):
        raise ValueError("args must be a list")

    try:
        result = {'type': 'function_expression', 'children': args, 'value': name}
        return result
    except Exception as e:
        raise ValueError(f"Failed to create function expression AST node: {str(e)}")

