def create_multi_select_list_ast_node(nodes: list[dict[str, object]]) -> dict[str, object]:
    """Create an AST node representing a multi-select list operation in a JMESPath expression. nodes: Array of AST nodes to include in the multi-select list, e.g. [{"type": "field", "value": "a"}, {"type": "field", "value": "b"}] -> {"type": "multi_select_list", "children": [{"type": "field", "value": "a"}, {"type": "field", "value": "b"}]}."""
    if not isinstance(nodes, list):
        raise ValueError("nodes must be an array")

    # Validate each node is a dictionary
    for i, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise ValueError(f"each node must be a dictionary, found {type(node)} at index {i}")

    return {"type": "multi_select_list", "children": nodes}

